// Problems are states (alert once, remind hourly, report recovery);
// failed cards and execution errors are events (reported once).
const cfg = $("Watchdog settings").first().json;
const now = Date.now();
const min = ms => Math.round(ms / 60000);
const warsaw = v => new Intl.DateTimeFormat("pl-PL", { timeZone: "Europe/Warsaw", dateStyle: "short", timeStyle: "medium" }).format(new Date(v));
const rows = $("Read state").all().map(i => i.json).filter(r => r.name);
const byName = Object.fromEntries(rows.map(r => [r.name, r]));
const service = byName.service || {}, monitor = byName.monitor || {};
const interval = Number(service.interval_seconds) || 20;
let prev = {};
try { prev = JSON.parse(byName.watchdog?.alerts_json || "{}") || {}; } catch (e) { prev = {}; }
const active = prev.active || {};
const searches = $("Read searches").all().map(i => i.json).filter(s => s.search_id);
const queue = $("Read queue").all().map(i => i.json).filter(n => n.item_id);
const wfResp = $("Production workflows").first().json;
const exResp = $("Execution errors").first().json;

const problems = {};
const events = [];
const workflows = wfResp.statusCode === 200 && Array.isArray(wfResp.body?.data) ? wfResp.body.data : null;
if (!workflows) problems.api = "No access to the n8n API (HTTP " + (wfResp.statusCode ?? "—") + "): watchdog cannot see workflow state.";
const isActive = id => workflows?.find(w => w.id === id)?.active === true;
const monitorOn = isActive(cfg.monitor_id), senderOn = isActive(cfg.sender_id);

// Monitoring is on but has not finished a cycle for 5 intervals (at least 5 minutes).
if (monitorOn) {
  const last = Date.parse(monitor.last_completed_at || monitor.finished_at || "");
  const limit = Math.max(5 * interval, 300) * 1000;
  if (!Number.isFinite(last) || now - last > limit)
    problems.stalled = "Monitoring is on but has not completed a cycle " + (Number.isFinite(last) ? min(now - last) + " min (last " + warsaw(last) + ")" : "never") + ".";
}

// Per-search problems: 429 for more than 3 intervals, other errors for more than 30 minutes, HTML fallback.
if (monitorOn) {
  const limited = [], html = [];
  for (const s of searches.filter(s => s.enabled)) {
    const error = String(s.last_error || "");
    if (!error) continue;
    const label = s.name + " (" + s.search_id + ")";
    if (error.startsWith("JSON unavailable, HTML used")) { html.push(label); continue; }
    const since = Date.parse(s.last_success_at || s.createdAt || "");
    const age = Number.isFinite(since) ? now - since : Infinity;
    if (error.startsWith("Marketplace: HTTP 429")) { if (age > 3 * interval * 1000) limited.push(label); continue; }
    if (age > 30 * 60000)
      problems["search:" + s.search_id] = "Search " + label + " without a successful check " + (Number.isFinite(age) ? min(age) + " min" : "since it was added") + ": " + error.slice(0, 300);
  }
  if (limited.length) problems.rate = "Marketplace has been returning 429 for longer than " + 3 * interval + " s: " + limited.join(", ") + ".";
  if (html.length) problems.html = "Marketplace changed the page, using fallback HTML parsing: " + html.join(", ") + ".";
}

// The oldest pending card waits for more than 10 minutes while sending is on.
const pending = queue.filter(n => n.status === "pending");
if (senderOn && pending.length) {
  const oldest = Math.min(...pending.map(n => Date.parse(n.createdAt)));
  if (now - oldest > 10 * 60000)
    problems.queue = "Queue is stuck: waiting " + pending.length + ", oldest " + min(now - oldest) + " min.";
}

// Cards the sender gave up on stay as status=failed until the nightly cleanup.
const failed = queue.filter(n => n.status === "failed");
const seenFailed = new Set(prev.failed_ids || []);
for (const n of failed.filter(n => !seenFailed.has(n.id))) {
  let p = {};
  try { p = JSON.parse(n.payload_json || "{}"); } catch (e) {}
  events.push("Card not delivered after 3 attempts: " + (p.title || n.item_id) + " (search " + (p.search_name || n.search_id) + "). " + String(n.last_error || "").slice(0, 300));
}

// Execution errors since the previous check, grouped by workflow.
let errorsSince = Number(prev.errors_since) || now;
let freshErrors = [];
const errorCounts = {};
if (exResp.statusCode === 200 && Array.isArray(exResp.body?.data)) {
  freshErrors = exResp.body.data.filter(e => Date.parse(e.startedAt) > errorsSince);
  if (freshErrors.length) {
    for (const e of freshErrors) {
      const name = workflows?.find(w => w.id === e.workflowId)?.name || e.workflowId;
      errorCounts[name] = (errorCounts[name] || 0) + 1;
    }
    events.push("Failed executions since " + warsaw(errorsSince) + ": " + Object.entries(errorCounts).map(([k, v]) => k + " — " + v).join(", ") + ". Details in Executions of the n8n editor.");
    errorsSince = Math.max(...freshErrors.map(e => Date.parse(e.startedAt)));
  }
} else problems.api = problems.api || "No access to the n8n API (HTTP " + (exResp.statusCode ?? "—") + "): watchdog cannot see execution errors.";

const messages = [];
for (const [key, text] of Object.entries(problems)) {
  const remindEvery = (key === "html" ? 24 * 60 : 60) * 60000;
  if (!active[key]) { messages.push("⚠️ " + text); active[key] = { text, since: now, sent: now }; }
  else {
    if (now - active[key].sent > remindEvery) { messages.push("⚠️ Still (since " + warsaw(active[key].since) + "): " + text); active[key].sent = now; }
    active[key].text = text;
  }
}
for (const key of Object.keys(active)) if (!problems[key]) {
  messages.push("✅ Recovered: " + active[key].text);
  delete active[key];
}
messages.push(...events.map(e => "❗ " + e));

const text = messages.length ? ("[" + cfg.label + "] Watchdog\n\n" + messages.join("\n\n")).slice(0, 3800) : "";

// One history sample per run for /history. CPU and execution rate are averages since the previous sample.
const metricsText = String($("n8n metrics").first().json.data ?? "");
const metric = name => { const m = metricsText.match(new RegExp("^" + name + "(?:\\{[^}]*\\})? (\\S+)$", "m")); return m ? Number(m[1]) : NaN; };
const runs = [...metricsText.matchAll(/^n8n_workflow_execution_duration_seconds_count(?:\{[^}]*\})? (\S+)$/gm)].reduce((s, m) => s + Number(m[1]), 0);
const cpuTotal = metric("n8n_process_cpu_seconds_total"), started = metric("n8n_process_start_time_seconds");
const last = prev.sample;
const restarted = !!last && Number.isFinite(started) && started !== last.start;
const span = last ? (now - last.at) / 1000 : 0;
const usable = last && !restarted && span > 0 && Number.isFinite(cpuTotal);
const round = (v, d = 1) => Number.isFinite(v) ? Math.round(v * 10 ** d) / 10 ** d : null;
const since = last ? last.at : now - 5 * 60000;
const sentNew = $("Read sent").all().map(i => i.json)
  .filter(n => n.item_id && Date.parse(n.sent_at) > since && Date.parse(n.sent_at) <= now);
const delays = sentNew.map(n => (Date.parse(n.sent_at) - Date.parse(n.createdAt)) / 1000).filter(d => Number.isFinite(d) && d >= 0);
const cycleMs = Date.parse(monitor.last_completed_at) - Date.parse(monitor.last_started_at);
const stale = searches.filter(s => s.enabled && s.initialized && s.last_success_at).map(s => (now - Date.parse(s.last_success_at)) / 1000).filter(Number.isFinite);
const rateNow = searches.filter(s => s.enabled && String(s.last_error || "").startsWith("Marketplace: HTTP 429")).map(s => s.name);
const sample = {
  sampled_at: new Date(now).toISOString(),
  cpu_pct: usable ? round((cpuTotal - last.cpu) / span * 100) : null,
  rss_mb: round(metric("n8n_process_resident_memory_bytes") / 1048576, 0),
  lag_ms: round(metric("n8n_nodejs_eventloop_lag_p99_seconds") * 1000),
  exec_rate: usable ? round((runs - last.runs) / span, 2) : null,
  cycle_s: Number.isFinite(cycleMs) && cycleMs >= 0 ? round(cycleMs / 1000) : null,
  queue: pending.length,
  stale_s: stale.length ? round(Math.max(...stale), 0) : null,
  cards: sentNew.length,
  delay_avg_s: delays.length ? round(delays.reduce((a, b) => a + b, 0) / delays.length) : null,
  delay_max_s: delays.length ? round(Math.max(...delays)) : null,
  retries: sentNew.filter(n => Number(n.attempts) > 0).length,
  errors: freshErrors.length,
  notes: JSON.stringify({
    rate: rateNow, errors: errorCounts, restart: restarted,
    failed: failed.filter(n => !seenFailed.has(n.id)).map(n => { try { return JSON.parse(n.payload_json || "{}").title || n.item_id; } catch (e) { return n.item_id; } }),
    alerts: messages.filter(m => !m.startsWith("❗") && !m.startsWith("⚠️ Still")),
  }),
};
const state = JSON.stringify({ active, failed_ids: failed.map(n => n.id), errors_since: errorsSince,
  sample: Number.isFinite(cpuTotal) ? { at: now, cpu: cpuTotal, start: started, runs } : null });
return [{ json: { text, state, sample, chat_id: String(cfg.admin_chat_id) } }];
